const {definitions,presets,evaluate}=EntryEngine;const $=id=>document.getElementById(id);let current={broken:'unknown'},automatic={broken:'unknown'},records=[],mode='auto',generation=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('fields').innerHTML=definitions.map(([id,label,min,max,unit,help])=>`<div class="field"><label for="${id}">${label}</label><div class="input-row"><input id="${id}" type="number" min="${min}" max="${max}" step="any" placeholder="未知"><span>${unit}</span></div><small>${help}</small></div>`).join('');
try{const p=JSON.parse(localStorage.getItem('entry-preferences')||'{}');if([...$('symbol').options].some(o=>o.value===p.symbol))$('symbol').value=p.symbol;if(['20','60'].includes(p.horizon))$('horizon').value=p.horizon;}catch{}
const requestedSymbol=new URLSearchParams(location.search).get('symbol');if([...$('symbol').options].some(o=>o.value===requestedSymbol))$('symbol').value=requestedSymbol;
function sync(){for(const[id]of definitions)$(id).value=current[id]??'';$('broken').value=current.broken||'unknown';}
function render(){const layered=EntryLayers(current);$('environment-layer').textContent=layered.environment;$('technical-layer').textContent=layered.technical;$('confirmation-layer').textContent=layered.confirmation;const r=evaluate(current),isIndex=['SPY','SOXX'].includes($('symbol').value);$('selected').textContent=$('symbol').selectedOptions[0].textContent;$('decision').textContent=mode==='auto'?(isIndex?layered.environment:layered.headline):r.decision;$('explanation').textContent=mode==='auto'?'技术层先判断价格行为；估值与基本面独立确认。技术候选不是完整买入建议。':r.explanation;$('coverage').textContent=`${r.coverage} / 11`;$('period').textContent=`评估窗口：${$('horizon').value} 个交易日 · 阈值尚未回测`;$('mode').textContent=mode==='demo'?'演示情景 · 全部为假设数值，不代表当前行情。':mode==='manual'?'手动试算 · 包含未经核验的输入，不能视为实时市场判断。':'自动观察 · 仅使用已获取且未过期的数据，缺失项保持未知。';for(const k of ['panic','trend']){$(`${k}-score`).textContent=r[k].filter(x=>x.status==='yes').length;$(`${k}-checks`).innerHTML=r[k].map(x=>`<div class="check"><span>${x.label}</span><b class="${x.status}">${{yes:'✓ 成立',no:'未满足',unknown:'待数据'}[x.status]}</b></div>`).join('');}
const next=[];if(current.broken!=='no')next.push(current.broken==='yes'?'基本面已失效，需要重新评估经营假设。':'基本面事件尚待核实。');const path=r.panic.filter(x=>x.status==='yes').length>=r.trend.filter(x=>x.status==='yes').length?r.panic:r.trend;path.filter(x=>x.status!=='yes').forEach(x=>next.push(`${x.status==='unknown'?'数据待接入':'条件未成立'}：${x.label}。`));if(!next.length)next.push('当前试算条件齐备；核实来源、日期及近期事件。');$('next').innerHTML=next.map(s=>`<li>${esc(s)}</li>`).join('');$('sources').innerHTML=records.length?records.map(s=>`<div class="source-row"><div><strong>${esc(s.label)}</strong><p>${esc(s.message)}</p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.source)}</a>`:''}</div><span class="${s.status==='ok'?'yes':'unknown'}">${esc(s.status==='ok'?'已获取':s.status==='stale'?'已过期':s.status==='cached'?'数据库旧记录':s.status==='review'?'待复核':'暂缺')}<br>${esc(s.date||'')}</span></div>`).join(''):'<p>尚无自动数据。请点击刷新。</p>';if(mode!=='auto')$('sources').insertAdjacentHTML('afterbegin','<p class="notice">以下来源仅对应自动数据，当前演示 / 手动试算未采用同一来源。</p>');}
async function refresh(){const g=++generation;mode='auto';automatic={broken:'unknown'};current={...automatic};records=[];sync();render();$('mode').textContent='正在获取可用数据…';$('refresh').disabled=true;try{const res=await fetch('/api/market?symbol='+encodeURIComponent($('symbol').value),{signal:AbortSignal.timeout(25000)});if(!res.ok)throw Error('请求失败');const d=await res.json();if(g!==generation)return;automatic={...d.values,broken:d.values?.broken||'unknown'};records=d.sources;current={...automatic};}catch(e){if(g!==generation)return;records=[{label:'自动数据',message:'暂时无法获取，请稍后刷新。未使用演示数据补齐。',status:'missing'}];}finally{if(g===generation){$('refresh').disabled=false;sync();render();}}}
function preset(name){if(!Object.hasOwn(presets,name))throw Error('未知情景');generation++;$('refresh').disabled=false;mode='demo';current={...presets[name],market50:presets[name].market};$('lab').open=true;sync();render();}
for(const[id]of definitions)$(id).addEventListener('input',()=>{generation++;$('refresh').disabled=false;current[id]=$(id).value===''?null:Number($(id).value);mode='manual';render();});$('broken').addEventListener('change',()=>{generation++;$('refresh').disabled=false;current.broken=$('broken').value;mode='manual';render();});function savePref(){try{localStorage.setItem('entry-preferences',JSON.stringify({symbol:$('symbol').value,horizon:$('horizon').value}));}catch{}}
$('symbol').addEventListener('change',()=>{savePref();refresh();});$('horizon').addEventListener('change',()=>{savePref();render();});$('refresh').onclick=refresh;$('restore').onclick=refresh;document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>preset(b.dataset.preset));sync();refresh();
if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'set_demo_scenario',description:'打开实验室并切换假设情景，不代表实时行情。',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:Object.keys(presets)}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='scenario')||!Object.hasOwn(presets,input.scenario))throw Error('情景不合法');preset(input.scenario);return{mode,symbol:$('symbol').value,...evaluate(current)};}},{signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}

setInterval(()=>{if(mode==='auto'&&!document.hidden&&!$('refresh').disabled)refresh();},15*60*1000);
